from pathlib import Path
import json,csv,html,collections,urllib.parse
root=Path('docs/studio-lab-audit-current')
read=lambda name:json.loads((root/name).read_text(encoding='utf-8'))
before={r['key']:r for r in read('before-scores.json')};after={r['key']:r for r in read('after-scores.json')}
labels={'carbohydrate':'Carbohydrate Structure Studio','nucleic':'Nucleic Acid Explorer','drug':'Drug Discovery Studio','physical':'Physical Chemistry Studio','pharma':'Pharmaceutical Chemistry Lab','primary':'Top-level designs (including overlapping overviews)'}
rows=[];groups=collections.OrderedDict()
for key,a in after.items():
 b=before[key];group=a['family'] if a['family']!='virtual-labs' else urllib.parse.urlsplit(a['route']).fragment.strip('/').split('?')[0]
 label=labels.get(group,a['title'].split(' / ')[0]);entry={**a,'group':group,'groupLabel':label,'beforePercent':b['ssimPercent'],'afterPercent':a['ssimPercent'],'deltaPoints':round(a['ssimPercent']-b['ssimPercent'],1),'beforeCapture':b['capture']};rows.append(entry);groups.setdefault(group,[]).append(entry)
summary=[{'group':g,'label':r[0]['groupLabel'],'screens':len(r),'beforePercent':round(sum(x['beforePercent'] for x in r)/len(r),1),'afterPercent':round(sum(x['afterPercent'] for x in r)/len(r),1)} for g,r in groups.items()]
labs=list({r['route']:r for r in read('lab-navigation.json')}.values());studios=read('studio-navigation.json');mobile=read('mobile-checks.json')
report={'date':'2026-10-17','references':233,'beforeCaptures':len(before),'afterCaptures':len(after),'method':'Grayscale SSIM, 11px window, images normalized to 836 x 470; browser viewport 1672 x 941. This is screenshot similarity, not feature completion or a scientific accuracy rating. Animated poses, startup state, text and verified data differences affect the score.','referenceRoots':['C:/Indian Servers/temp/Chemistry web/TargetUI','D:/Chemistry UI Upgrading/Chemistry-VL-complete-mockups'],'styleIsolation':{'labRoots':19,'scopedSelectors':3812,'separateSolverAndCarbohydrateNamespaces':True},'physicalAnalysisTabs':50,'unscoredDestinationsWithoutDedicatedTargets':91,'routing':{'studioDestinations':sum(len(r['steps']) for r in studios),'studioDestinationsPassed':all(r['passed'] for r in studios),'labScreenLinks':sum(len(r['steps']) for r in labs),'labScreenLinksPassed':all(r['passed'] for r in labs),'labsWithBackForwardReload':len(labs),'routeRegressionAssertions':178},'renderErrors':[r['key'] for r in rows if r.get('error')],'unfinishedViewers':sum(r.get('loadingViewers',0) for r in rows),'mobileOverflowChecks':mobile,'productionBuild':'passed','chemistryTests':'25 biochemistry models, 56 syllabus models, 13 physical workspaces; 15 normalized hydrogen states; 13 pharmaceutical calculations. Molecular framing, lab routing, CSS isolation, Maxwell distribution, MSD slope, VACF and energy consistency tests passed. All 50 physical-analysis tabs passed browser checks.','new3D':['Independent Chemistry Solver CSS namespace and 3,812 lab selectors isolated from other pages','Nine procedural instrument overviews with orbit, zoom, animation, reset and fullscreen','Procedural apparatus in syllabus and organic preparation benches','Orbitable Molecular Dynamics particle boxes','Calculated hydrogen probability-density isosurfaces with opposite phase colors','Chain-colored COX-2 homodimer and separate binding-pocket view','Six-vessel dissolution tester with an autosampler and live paddle controls'],'runtimeTargetScreenshotReferences':0,'remainingGaps':['91 additional catalogue destinations do not have dedicated reference screenshots and have not been assigned invented visual percentages.','Visual parity is incomplete. Most studio group screenshot-similarity averages have not improved; the largest improvement is the restored Molecular Dynamics lab.','Several apparatus and anatomy designs remain less detailed than the target illustrations. Density, annotations and panel arrangement still differ on many screens.','The dedicated MD lesson uses labelled analytical examples; force-integrated trajectories are available in the separate physical studio. The lesson is not a trajectory-analysis engine.','Navigation was verified for all 49 dedicated studio screens and all 115 complete-lab screens; every control across all 233 pages was not exhaustively certified.','Overlapping top-level and dedicated screenshots sometimes request different designs for the same URL; dedicated studio and complete-lab references take precedence.'],'groups':summary,'screens':rows}
(root/'audit-report.json').write_text(json.dumps(report,indent=2,ensure_ascii=False),encoding='utf-8')
with (root/'visual-match.csv').open('w',encoding='utf-8-sig',newline='') as file:
 writer=csv.writer(file);writer.writerow(['Studio or lab','Screen','Route','Before SSIM %','After SSIM %','Difference (points)','Reference image','Updated screenshot'])
 for r in rows:writer.writerow([r['groupLabel'],r['title'],r['route'],r['beforePercent'],r['afterPercent'],r['deltaPoints'],r['reference'],r['capture']])
e=html.escape
body=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Studio and lab TargetUI audit</title><style>body{margin:0;background:#071522;color:#d5e8fa;font:14px/1.6 system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:28px}h1{margin:0;font-size:30px}p{max-width:1000px;color:#abc5dc}a{color:#5dc6ff}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:9px 12px;border-bottom:1px solid #234057}th{background:#123049;position:sticky;top:0}td.num{font-variant-numeric:tabular-nums}section{margin:30px 0}.cards{display:flex;gap:12px;flex-wrap:wrap}.cards>div{background:#123049;padding:18px;border:1px solid #285371;border-radius:9px}.cards b{display:block;font-size:27px;color:#66dfb6}input,select{font:inherit;border:1px solid #3a637d;border-radius:6px;background:#102b3f;color:#d6edff;padding:10px;margin:8px 8px 14px 0}input{width:min(470px,80%)}details.case{border:1px solid #26455b;background:#0d2233;margin:9px 0;border-radius:7px}summary{cursor:pointer;padding:13px}summary span{color:#73c5f9;float:right;font-variant-numeric:tabular-nums}.case>p{padding:0 15px}.comparison{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;padding:12px}figure{margin:0;min-width:0}figcaption{font-size:12px;color:#9cb9d2}img{width:100%;height:auto;display:block;border:1px solid #345770}.notice{background:#332c19;border:1px solid #8e7435;padding:15px;border-radius:8px}.foot{font-size:12px;color:#8da8bf}@media(max-width:800px){main{padding:16px}.comparison{grid-template-columns:1fr}table{font-size:11px}td,th{padding:7px 4px}summary span{float:none;display:block}}</style><main>']
body+=['<h1>Studio and lab TargetUI audit</h1><p>17 October 2026 · 233 reference screens · native UI and geometry; no mockup crops used in the app.</p>', '<div class="cards"><div><b>49 / 49</b>Studio destinations passed</div><div><b>115 / 115</b>Lab screen links passed</div><div><b>19 / 19</b>Labs: Back, Forward and reload passed</div><div><b>233 / 233</b>Updated captures, no route-render errors</div></div>', '<p class="notice">Visual parity remains incomplete. These percentages are measured screenshot similarity, not a claim of completion. Functional and 3D improvements do not guarantee a higher pixel-similarity score. Some group averages remain unchanged or lower.</p>', '<p>'+e(report['method'])+'</p><p>References: dedicated TargetUI studio designs and the existing complete-lab mockup set. Correct chemistry, deposited coordinates and labelled calculated examples take precedence over illustrative target values. Conflicting designs that share a URL are listed separately.</p><section><h2>Before / after by studio and lab</h2><table><thead><tr><th>Studio or lab</th><th>Screens</th><th>Before</th><th>After</th></tr></thead><tbody>']
for r in summary:body.append(f'<tr><td>{e(r["label"])}</td><td>{r["screens"]}</td><td class="num">{r["beforePercent"]:.1f}%</td><td class="num">{r["afterPercent"]:.1f}%</td></tr>')
body+=['</tbody></table></section><section><h2>Changes and verification</h2><ul>']
for text in report['new3D']:body.append('<li>'+e(text)+'</li>')
body+=['</ul><p>'+e(report['chemistryTests'])+' Production build passed. Seven changed studio/lab layouts passed 390px overflow checks. Apparatus animation, pause and camera reset were verified with distinct animation frames.</p><h2>Remaining gaps</h2><ul>']
for text in report['remainingGaps']:body.append('<li>'+e(text)+'</li>')
body+=['</ul></section><section><h2>All 233 screen comparisons</h2><input id="search" placeholder="Search studio, lab, screen or route"><select id="family"><option value="">All groups</option>']
for r in summary:body.append('<option value="'+e(r['group'])+'">'+e(r['label'])+'</option>')
body+=['</select><p id="count">233 screens</p>']
for r in rows:
 body.append(f'<details class="case" data-group="{e(r["group"])}"><summary>{e(r["groupLabel"])} — {e(r["title"])}<span>{r["beforePercent"]:.1f}% → {r["afterPercent"]:.1f}%</span></summary><p><a href="{e(urllib.parse.urljoin("http://127.0.0.1:5189/",r["route"]))}">Open this workspace</a> · {e(r["route"])}</p><div class="comparison">')
 for label,path in [('Target reference',r['reference']),('Before',r['beforeCapture']),('After',r['capture'])]:body.append('<figure><figcaption>'+label+'</figcaption><a href="'+e(Path(path).resolve().as_uri())+'"><img loading="lazy" src="'+e(Path(path).resolve().as_uri())+'" alt="'+e(label+' '+r['title'])+'"></a></figure>')
 body.append('</div></details>')
body+=['</section><p class="foot">Audit images are comparison evidence only. Target mockups are not runtime assets. Data and screenshot paths are recorded in audit-report.json and visual-match.csv.</p></main><script>const search=document.getElementById("search"),family=document.getElementById("family"),cases=[...document.querySelectorAll(".case")];function filter(){let n=0;for(const item of cases){const show=(!family.value||item.dataset.group===family.value)&&item.textContent.toLowerCase().includes(search.value.toLowerCase());item.hidden=!show;if(show)n++;}document.getElementById("count").textContent=n+" screens";}search.addEventListener("input",filter);family.addEventListener("change",filter);</script></html>']
(root/'audit-report.html').write_text(''.join(body),encoding='utf-8');print('Created full audit: 233 comparisons, CSV, JSON and searchable HTML.')
